Utility functions like countBy and trueCount should be robust against non-array inputs by returning safe defaults (such as an empty object or zero) to fail closed gracefully instead of throwing a TypeError.

```javascript
function countBy(rows, selector) {
  if (!Array.isArray(rows)) return {};
  const counts = {};
  for (const row of rows) {
    const value = selector(row);
    const key = value === null || value === undefined || value === '' ? 'missing' : String(value);
    counts[key] = (counts[key] ?? 0) + 1;
  }
  return Object.fromEntries(Object.entries(counts).sort(([left], [right]) => (
    Buffer.compare(Buffer.from(left), Buffer.from(right))
  )));
}

function trueCount(rows, selector) {
  if (!Array.isArray(rows)) return 0;
  return rows.filter((row) => selector(row) === true).length;
}
```

